def topo_sort(graph):
    """
    Perform topological sort on a directed graph.

    Args:
        graph: dict mapping node -> list of dependencies (nodes that must come before)

    Returns:
        List of nodes in topological order (dependencies before dependents),
        or None if the graph contains a cycle.
    """
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}
    result = []

    def dfs(node):
        color[node] = GRAY
        for dep in graph.get(node, []):
            if dep not in color:
                color[dep] = WHITE
            if color[dep] == GRAY:
                return False  # cycle detected
            if color[dep] == WHITE:
                if not dfs(dep):
                    return False
        color[node] = BLACK
        result.append(node)
        return True

    for node in graph:
        if color[node] == WHITE:
            if not dfs(node):
                return None

    # Also handle any dependencies that might not be keys in graph
    for node in list(result):
        for dep in graph.get(node, []):
            if dep not in color:
                color[dep] = WHITE
                if not dfs(dep):
                    return None

    return result
```

