def parse_csv(text):
    lines = text.strip().splitlines()
    if not lines:
        return []

    def parse_line(line):
        fields = []
        current = []
        in_quotes = False
        i = 0
        while i < len(line):
            ch = line[i]
            if in_quotes:
                if ch == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        current.append('"')
                        i += 2
                        continue
                    else:
                        in_quotes = False
                        i += 1
                        continue
                else:
                    current.append(ch)
                    i += 1
                    continue
            else:
                if ch == '"':
                    in_quotes = True
                    i += 1
                    continue
                elif ch == ',':
                    fields.append(''.join(current))
                    current = []
                    i += 1
                    continue
                else:
                    current.append(ch)
                    i += 1
                    continue
        fields.append(''.join(current))
        return fields

    header = parse_line(lines[0])
    result = []
    for line in lines[1:]:
        if not line.strip():
            continue
        values = parse_line(line)
        row = {}
        for i, h in enumerate(header):
            row[h] = values[i] if i < len(values) else ''
        result.append(row)
    return result
```

