def is_balanced(s):
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set('([{')
    for char in s:
        if char in opening:
            stack.append(char)
        elif char in matching:
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()
    return not stack
```

