def deep_get(obj, path, default=None):
    """
    Read a dotted path out of nested dicts and lists.
    List indices appear as digits in the path.
    Returns default when any step is missing.
    """
    if path is None or path == "":
        return obj

    parts = path.split(".")
    current = obj

    for part in parts:
        if current is None:
            return default

        if isinstance(current, dict):
            if part in current:
                current = current[part]
            else:
                return default
        elif isinstance(current, (list, tuple)):
            try:
                index = int(part)
            except ValueError:
                return default
            if -len(current) <= index < len(current):
                current = current[index]
            else:
                return default
        else:
            return default

    return current
```

