import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")

    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    pattern = re.compile(r'(\d+)([dhms])')
    matches = pattern.findall(s)

    if not matches:
        raise ValueError(f"Unparseable duration: '{s}'")

    # Check that the entire string is consumed by the pattern
    reconstructed = ''.join(f"{num}{unit}" for num, unit in matches)
    if reconstructed != s:
        raise ValueError(f"Unparseable duration: '{s}'")

    # Check for duplicate units
    units_seen = set()
    for num, unit in matches:
        if unit in units_seen:
            raise ValueError(f"Duplicate unit '{unit}' in duration: '{s}'")
        units_seen.add(unit)

    unit_to_seconds = {
        'd': 86400,
        'h': 3600,
        'm': 60,
        's': 1,
    }

    total = 0
    for num, unit in matches:
        total += int(num) * unit_to_seconds[unit]

    return total
```

