def run_length_encode(s):
    if not s:
        return []
    pairs = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            pairs.append((current_char, count))
            current_char = char
            count = 1
    pairs.append((current_char, count))
    return pairs

def run_length_decode(pairs):
    result = []
    for char, count in pairs:
        result.append(char * count)
    return ''.join(result)
