import re

def mask_secrets(text):
    secret_keys = ('password', 'token', 'key')

    def replace_match(match):
        key = match.group(1)
        if any(secret in key.lower() for secret in secret_keys):
            return f"{key}=***"
        return match.group(0)

    # Match k=v pairs where k is a word/identifier and v is everything until next pair or end
    pattern = r'(\w+)=([^=\s]+)'
    return re.sub(pattern, replace_match, text)
