function debounceCount(fn, ms) {
  let timer = null;
  let pendingArgs = null;
  let pendingThis = null;

  function call(...args) {
    pendingArgs = args;
    pendingThis = this;
    if (timer !== null) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = null;
      const argsToUse = pendingArgs;
      const thisToUse = pendingThis;
      pendingArgs = null;
      pendingThis = null;
      fn.apply(thisToUse, argsToUse);
    }, ms);
  }

  function flush() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
      const argsToUse = pendingArgs;
      const thisToUse = pendingThis;
      pendingArgs = null;
      pendingThis = null;
      fn.apply(thisToUse, argsToUse);
    }
  }

  return { call, flush };
}

module.exports = debounceCount;
```

