function rotateArray(arr, k) {
  if (!Array.isArray(arr) || arr.length === 0) {
    return [];
  }

  const n = arr.length;
  // Normalize k to be within [0, n)
  let shift = ((k % n) + n) % n;

  // Rotate right by shift: last 'shift' elements move to front
  const result = arr.slice(n - shift).concat(arr.slice(0, n - shift));

  return result;
}

module.exports = rotateArray;
